-- FETAN independent editorial and verified match data (PostgreSQL)
-- Run only against a dedicated FETAN database.
CREATE TABLE IF NOT EXISTS fetan_teams (id BIGSERIAL PRIMARY KEY, name TEXT NOT NULL, slug TEXT UNIQUE NOT NULL, crest_url TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS fetan_competitions (id BIGSERIAL PRIMARY KEY, name TEXT NOT NULL, slug TEXT UNIQUE NOT NULL, season TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS fetan_matches (id BIGSERIAL PRIMARY KEY, competition_id BIGINT NOT NULL REFERENCES fetan_competitions(id), home_team_id BIGINT NOT NULL REFERENCES fetan_teams(id), away_team_id BIGINT NOT NULL REFERENCES fetan_teams(id), kickoff_at TIMESTAMPTZ NOT NULL, status TEXT NOT NULL DEFAULT 'scheduled' CHECK(status IN ('scheduled','live','halftime','finished','postponed','cancelled')), home_score INT CHECK(home_score>=0), away_score INT CHECK(away_score>=0), verified_at TIMESTAMPTZ, verified_by TEXT, source_note TEXT, updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK(home_team_id<>away_team_id));
CREATE INDEX IF NOT EXISTS fetan_matches_kickoff_idx ON fetan_matches(kickoff_at);
CREATE TABLE IF NOT EXISTS fetan_match_events (id BIGSERIAL PRIMARY KEY, match_id BIGINT NOT NULL REFERENCES fetan_matches(id) ON DELETE CASCADE, event_type TEXT NOT NULL CHECK(event_type IN ('goal','red_card','yellow_card','substitution','kickoff','halftime','fulltime')), minute INT CHECK(minute BETWEEN 0 AND 130), team_id BIGINT REFERENCES fetan_teams(id), player_name TEXT, description TEXT, verified_at TIMESTAMPTZ, verified_by TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS fetan_articles (id BIGSERIAL PRIMARY KEY, slug TEXT UNIQUE NOT NULL, title TEXT NOT NULL, summary TEXT, body TEXT NOT NULL, author_name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published')), published_at TIMESTAMPTZ, verified_by TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS fetan_notification_preferences (user_id BIGINT PRIMARY KEY, goals BOOLEAN NOT NULL DEFAULT TRUE, kickoff BOOLEAN NOT NULL DEFAULT TRUE, fulltime BOOLEAN NOT NULL DEFAULT TRUE, news BOOLEAN NOT NULL DEFAULT FALSE, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS fetan_follows (user_id BIGINT NOT NULL, team_id BIGINT NOT NULL REFERENCES fetan_teams(id), PRIMARY KEY(user_id,team_id));
CREATE TABLE IF NOT EXISTS fetan_notification_outbox (id BIGSERIAL PRIMARY KEY, dedupe_key TEXT UNIQUE NOT NULL, user_id BIGINT NOT NULL, event_type TEXT NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL, target_url TEXT NOT NULL DEFAULT '/', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), sent_at TIMESTAMPTZ);
-- Private application tables: no anonymous grants. Use a server-side DB credential only.
REVOKE ALL ON fetan_teams, fetan_competitions, fetan_matches, fetan_match_events, fetan_articles, fetan_notification_preferences, fetan_follows, fetan_notification_outbox FROM PUBLIC;
